-- 5.3 Jumlah UDF per tabel standar SAP (tabel UDT dan tabel arsip A* yang hanya salinan UDF tabel lain tidak termasuk)
SELECT F."TableID", COUNT(*) AS "Fields" FROM CUFD F WHERE "TableID" NOT LIKE '@%' AND NOT (F."TableID" LIKE 'A%' AND EXISTS (SELECT 1 FROM CUFD X WHERE X."AliasID" = F."AliasID" AND X."TableID" NOT LIKE 'A%' AND X."TableID" NOT LIKE '@%')) GROUP BY F."TableID" ORDER BY F."TableID"
